import'package:flutter/material.dart';import'../../core/network/api_client.dart';import'../../core/security/session_store.dart';
class ChangePasswordScreen extends StatefulWidget{const ChangePasswordScreen({super.key,required this.api,required this.session});final ApiClient api;final SessionStore session;@override State<ChangePasswordScreen>createState()=>_State();}class _State extends State<ChangePasswordScreen>{final current=TextEditingController(),next=TextEditingController();String?error;bool busy=false;Future<void>save()async{setState(()=>busy=true);try{await widget.api.dio.post('/api/v1/users/me/change-password',data:{'currentPassword':current.text,'newPassword':next.text});await widget.session.clear();}catch(_){if(mounted)setState(()=>error='Modpas la pa chanje. Verifye ansyen modpas la ak règ sekirite yo.');}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Change password')),body:ListView(padding:const EdgeInsets.all(24),children:[const Text('Ou dwe chanje modpas tanporè a anvan ou kontinye.'),const SizedBox(height:16),TextField(controller:current,obscureText:true,decoration:const InputDecoration(labelText:'Current password',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:next,obscureText:true,decoration:const InputDecoration(labelText:'New password',helperText:'Minimum 12 characters',border:OutlineInputBorder())),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:const TextStyle(color:Colors.red))),const SizedBox(height:16),FilledButton(onPressed:busy?null:save,child:Text(busy?'Saving...':'Change password'))]));}
